assignment.solutionCode:
function squadLeader(squad) {
  for (const member of squad) {
    if (member.rank === 1) {
      return member.name;
    }
  }
  return undefined;
}

const squad = [
  { name: "Mira", rank: 2 },
  { name: "Talia", rank: 1 },
  { name: "Rook", rank: 3 },
];
console.log(squadLeader(squad));

